-- ─── Toggle rows ────────────────────────────────────────────────────────────
local antiBatAnimate, infJumpAnimate

local function makeToggle(parent, y, label, initialState, onToggle)
    local row = Instance.new("Frame")
    row.Position               = UDim2.new(0, 12, 0, y)
    row.Size                   = UDim2.new(1, -24, 0, isMobile and 38 or 50)
    row.BackgroundColor3       = theme.dark
    row.BackgroundTransparency = 0.5
    row.ZIndex                 = 4
    row.Parent                 = parent
    Instance.new("UICorner", row).CornerRadius = UDim.new(0, 12)

    local text = Instance.new("TextLabel")
    text.Position               = UDim2.new(0, 14, 0.5, -9)
    text.Size                   = UDim2.new(0, 105, 0, 18)
    text.BackgroundTransparency = 1
    text.Text                   = label
    text.TextColor3             = label == "Anti Bat" and theme.accent or theme.white
    text.TextSize               = isMobile and 12 or 14
    text.Font                   = Enum.Font.GothamBlack
    text.TextXAlignment         = Enum.TextXAlignment.Left
    text.ZIndex                 = 6
    text.Parent                 = row

    local rowStroke = Instance.new("UIStroke")
    rowStroke.Color = theme.accent
    rowStroke.Thickness = label == "Anti Bat" and 1.7 or 1.25
    rowStroke.Transparency = label == "Anti Bat" and 0.18 or 0.42
    rowStroke.Parent = row

    local rowGradient = Instance.new("UIGradient")
    rowGradient.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(8, 35, 65)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(5, 5, 7))
    })
    rowGradient.Rotation = 90
    rowGradient.Parent = row

    -- Round black ON/OFF control with a bright blue ring and orb.
    local track = Instance.new("Frame")
    track.Name = "RoundToggle"
    track.AnchorPoint = Vector2.new(1, 0.5)
    track.Position = UDim2.new(1, -17, 0.5, 0)
    track.Size = UDim2.fromOffset(30, 30)
    track.BackgroundColor3 = Color3.fromRGB(2, 5, 12)
    track.BorderSizePixel = 0
    track.ZIndex = 6
    track.Parent = row
    Instance.new("UICorner", track).CornerRadius = UDim.new(1, 0)
    local trackStroke = Instance.new("UIStroke")
    trackStroke.Color = initialState and Color3.fromRGB(45, 210, 255) or Color3.fromRGB(60, 85, 110)
    trackStroke.Thickness = 2
    trackStroke.Transparency = initialState and 0 or 0.18
    trackStroke.Parent = track

    local knob = Instance.new("Frame")
    knob.Name = "Orb"
    knob.AnchorPoint = Vector2.new(0.5, 0.5)
    knob.Position = UDim2.fromScale(0.5, 0.5)
    knob.Size = UDim2.fromOffset(initialState and 17 or 13, initialState and 17 or 13)
    knob.BackgroundColor3 = initialState and Color3.fromRGB(0, 175, 255) or Color3.fromRGB(15, 18, 24)
    knob.BorderSizePixel = 0
    knob.ZIndex = 7
    knob.Parent = track
    Instance.new("UICorner", knob).CornerRadius = UDim.new(1, 0)
    local knobStroke = Instance.new("UIStroke")
    knobStroke.Color = initialState and Color3.fromRGB(180, 245, 255) or Color3.fromRGB(90, 105, 125)
    knobStroke.Thickness = 1.2
    knobStroke.Transparency = 0.08
    knobStroke.Parent = knob

    local stateText = Instance.new("TextLabel")
    stateText.Name = "ToggleState"
    stateText.AnchorPoint = Vector2.new(1, 0.5)
    stateText.Position = UDim2.new(1, -56, 0.5, 0)
    stateText.Size = UDim2.fromOffset(27, 16)
    stateText.BackgroundTransparency = 1
    stateText.Text = initialState and "ON" or "OFF"
    stateText.TextColor3 = initialState and Color3.fromRGB(70, 210, 255) or Color3.fromRGB(155, 165, 180)
    stateText.TextSize = isMobile and 8 or 9
    stateText.Font = Enum.Font.GothamBlack
    stateText.TextXAlignment = Enum.TextXAlignment.Right
    stateText.ZIndex = 7
    stateText.Parent = row

    local hit = Instance.new("TextButton")
    hit.Position               = UDim2.new(1, -51, 0, 0)
    hit.Size                   = UDim2.fromOffset(48, isMobile and 38 or 50)
    hit.BackgroundTransparency = 1
    hit.Text                   = ""
    hit.ZIndex                 = 10
    hit.Parent                 = row

    local function animate(state)
        local orbColor = state and Color3.fromRGB(0, 175, 255) or Color3.fromRGB(15, 18, 24)
        local ringColor = state and Color3.fromRGB(45, 210, 255) or Color3.fromRGB(60, 85, 110)
        local textColor = state and Color3.fromRGB(70, 210, 255) or Color3.fromRGB(155, 165, 180)
        TweenService:Create(knob, TweenInfo.new(0.18, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
            { Size = UDim2.fromOffset(state and 17 or 13, state and 17 or 13), BackgroundColor3 = orbColor }):Play()
        TweenService:Create(trackStroke, TweenInfo.new(0.18), { Color = ringColor, Transparency = state and 0 or 0.18 }):Play()
        TweenService:Create(knobStroke, TweenInfo.new(0.18), { Color = state and Color3.fromRGB(180, 245, 255) or Color3.fromRGB(90, 105, 125) }):Play()
        stateText.Text = state and "ON" or "OFF"
        TweenService:Create(stateText, TweenInfo.new(0.18), { TextColor3 = textColor }):Play()
        TweenService:Create(rowStroke, TweenInfo.new(0.18), { Transparency = state and 0.03 or (label == "Anti Bat" and 0.25 or 0.48) }):Play()
        if label == "Anti Bat" then
            TweenService:Create(text, TweenInfo.new(0.18), { TextColor3 = state and Color3.fromRGB(115, 225, 255) or theme.white }):Play()
        end
    end

    hit.MouseButton1Click:Connect(function()
        playUISound()
        onToggle()
        if label == "Anti Bat" then animate(antiBatActive) else animate(infJumpActive) end
        refreshStatus()
        saveConfig()
    end)

    return animate
end

antiBatAnimate = makeToggle(content, isMobile and 44 or 48, "Anti Bat", config.AntiBatEnabled, function()
    if not antiBatActive then
        startAntiBat()
        config.AntiBatEnabled = true
    else
        stopAntiBat()
        config.AntiBatEnabled = false
    end
end)

infJumpAnimate = makeToggle(content, isMobile and 88 or 106, "Inf Jump", config.InfJumpEnabled, function()
    if not infJumpActive then
        startInfJump()
        infJumpAnimate(true)
    else
        stopInfJump()
        infJumpAnimate(false)
    end
end)

